<script>
  import SeoHead from '$lib/SeoHead.svelte';
  import { references, referenceEntries } from '$lib/data/references.js';

  let query = $state('');
  let technology = $state('all');
  const filteredEntries = $derived(referenceEntries.filter((entry) => {
    const text = `${entry.title} ${entry.description} ${entry.category} ${entry.example}`.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('fr');
    return (technology === 'all' || entry.technology === technology) && (!query.trim() || text.includes(query.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('fr')));
  }));
  const groups = $derived([...new Set(filteredEntries.map((entry) => `${entry.technology}:${entry.category}`))].map((key) => {
    const [entryTechnology, category] = key.split(':');
    const slug = key.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
    return { id: slug, technology: entryTechnology, category, entries: filteredEntries.filter((entry) => entry.technology === entryTechnology && entry.category === category) };
  }));
</script>

<SeoHead title="Références HTML, CSS, JavaScript et APIs Web — webschool.github.io" description="Consulte des fiches de référence HTML, CSS, JavaScript et APIs Web, reliées à la documentation MDN." path="/reference" />
<header class="page-heading"><span class="eyebrow">GARDER SOUS LA MAIN</span><h1>Documentation de référence</h1><p>Des liens vers les références MDN officielles. Elles détaillent la syntaxe, les paramètres, la compatibilité et les cas particuliers.</p></header>
<div class="reference-grid">{#each references as reference}<section id={reference.id} class="reference-card" style={`--reference-color:${reference.technology === 'html' ? '#b84f2c' : reference.technology === 'css' ? '#2569a8' : reference.technology === 'javascript' ? '#956e11' : '#54745a'}`}><span class="reference-symbol">&lt;/&gt;</span><h2>{reference.title}</h2><p>{reference.description}</p><ul>{#each reference.links as link}<li><a href={link.href} target="_blank" rel="noreferrer">{link.label}<span aria-hidden="true">↗</span></a></li>{/each}</ul></section>{/each}</div>
<section class="quick-reference"><div class="reference-heading"><div><span class="eyebrow">INDEX PÉDAGOGIQUE</span><h2>Références par catégorie</h2><p>{referenceEntries.length} fiches avec syntaxe, exemple et lien vers MDN.</p></div><label for="reference-search">Chercher une propriété ou méthode<input id="reference-search" type="search" bind:value={query} placeholder="Ex. : map, clamp, Fetch" /></label></div><label class="technology-filter" for="reference-technology">Technologie<select id="reference-technology" bind:value={technology}><option value="all">Toutes</option><option value="css">CSS</option><option value="javascript">JavaScript</option><option value="web">APIs Web</option></select></label><div class="reference-categories">{#each groups as group}<details id={`category-${group.id}`}><summary><span>{group.category}</span><small>{group.entries.length} notions · {group.technology.toUpperCase()}</small></summary><div>{#each group.entries as entry}<article id={entry.id}><div><h3>{entry.title}</h3><p>{entry.description}</p><pre><code>{entry.example}</code></pre></div><a href={entry.href} target="_blank" rel="noreferrer">Référence MDN ↗</a></article>{/each}</div></details>{/each}{#if groups.length === 0}<p class="no-reference-results">Aucune référence ne correspond à cette recherche.</p>{/if}</div></section>
<p class="reference-note">Les références complètes sont publiées et maintenues par MDN Web Docs. webschool.github.io y renvoie pour les détails exhaustifs.</p>

