  @media(max-width:650px){.reference-grid{grid-template-columns:1fr}}
  .quick-reference{margin-top:32px}.reference-heading{display:flex;align-items:end;justify-content:space-between;gap:18px;flex-wrap:wrap}.reference-heading h2{margin:6px 0;color:#2c3930;font:800 21px Manrope,system-ui,sans-serif}.reference-heading p{margin:0;color:#7a877d;font-size:11px}.reference-heading label,.technology-filter{display:grid;gap:5px;color:#58675d;font-size:10px;font-weight:700}.reference-heading input,.technology-filter select{min-width:190px;padding:9px;border:1px solid #dfe7df;border-radius:7px;background:#fff;color:#344239;font-size:11px}.technology-filter{width:max-content;margin:15px 0}.reference-categories{display:grid;gap:8px}.reference-categories details{border:1px solid #e5ebe5;border-radius:10px;background:#fff}.reference-categories summary{display:flex;justify-content:space-between;gap:10px;padding:13px 15px;color:#344239;font-size:12px;font-weight:750;cursor:pointer}.reference-categories summary small{color:#829087;font-size:9px;font-weight:500}.reference-categories details>div{border-top:1px solid #edf0ed}.reference-categories article{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 15px;border-bottom:1px solid #edf0ed}.reference-categories article:last-child{border-bottom:0}.reference-categories h3{margin:0;color:#344239;font-size:11px}.reference-categories article p{margin:4px 0;color:#748178;font-size:10px;line-height:1.5}.reference-categories pre{overflow:auto;max-width:720px;margin:6px 0 0;padding:7px 9px;border-radius:6px;background:#f5f8f5;color:#42654a;font:10px/1.5 ui-monospace,Consolas,monospace}.reference-categories article>a{white-space:nowrap;color:#267849;font-size:9px;font-weight:700;text-decoration:none}.no-reference-results{padding:18px;color:#79867d;font-size:11px}:global(.platform-shell[data-theme="dark"]) .quick-reference h2,:global(.platform-shell[data-theme="dark"]) .reference-categories h3{color:#eef4ee}:global(.platform-shell[data-theme="dark"]) .reference-categories details{border-color:#35443a;background:#202a23}:global(.platform-shell[data-theme="dark"]) .reference-categories details>div,:global(.platform-shell[data-theme="dark"]) .reference-categories article{border-color:#35443a}:global(.platform-shell[data-theme="dark"]) .reference-heading input,:global(.platform-shell[data-theme="dark"]) .technology-filter select{border-color:#405247;background:#1a241d;color:#e3ece4}:global(.platform-shell[data-theme="dark"]) .reference-categories pre{background:#1a241d;color:#c6ddca}@media(max-width:650px){.reference-heading{align-items:stretch;flex-direction:column}.reference-heading input{width:100%}.reference-categories article{align-items:flex-start;flex-direction:column}.reference-categories article>a{margin-top:4px}}
